+/****************************************************************************
+ * board/bk7258-devkit/scripts/flash_ap.ld
+ *
+ * Secure, single-core OpenVela AP linker script.  Physical CPU1 enters the
+ * vector table at the beginning of the AP raw payload.
+ ****************************************************************************/
+
+#include <nuttx/config.h>
+
+MEMORY
+{
+  flash (rx)  : ORIGIN = 0x02160000, LENGTH = 0x002a0000
+  sram  (rwx) : ORIGIN = CONFIG_RAM_START, LENGTH = CONFIG_RAM_SIZE
+}
+
+OUTPUT_ARCH(arm)
+EXTERN(_vectors)
+ENTRY(__start)
+
+BK7258_IDLE_STACK_RESERVATION = 0x800;
+
+SECTIONS
+{
+  .text :
+  {
+    _stext = ABSOLUTE(.);
+    . = ALIGN(512);
+    KEEP(*(.vectors))
+    *(.text .text.*)
+    *(.fixup)
+    *(.gnu.warning)
+    *(.rodata .rodata.*)
+    *(.gnu.linkonce.t.*)
+    *(.glue_7)
+    *(.glue_7t)
+    *(.got)
+    *(.gcc_except_table)
+    *(.gnu.linkonce.r.*)
+    _etext = ABSOLUTE(.);
+  } > flash
+
+  .init_section : ALIGN(4)
+  {
+    _sinit = ABSOLUTE(.);
+    KEEP(*(SORT_BY_INIT_PRIORITY(.init_array.*) SORT_BY_INIT_PRIORITY(.ctors.*)))
+    KEEP(*(.init_array EXCLUDE_FILE(*crtbegin.o *crtbegin?.o *crtend.o *crtend?.o) .ctors))
+    _einit = ABSOLUTE(.);
+  } > flash
+
+  .ARM.extab : ALIGN(4) { *(.ARM.extab*) } > flash
+  .ARM.exidx : ALIGN(4)
+  {
+    __exidx_start = ABSOLUTE(.);
+    *(.ARM.exidx*)
+    __exidx_end = ABSOLUTE(.);
+  } > flash
+
+  _eronly = ABSOLUTE(.);
+
+  .data : ALIGN(4)
+  {
+    _sdata = ABSOLUTE(.);
+    *(.data .data.*)
+    *(.gnu.linkonce.d.*)
+    CONSTRUCTORS
+    . = ALIGN(4);
+    _edata = ABSOLUTE(.);
+  } > sram AT > flash
+
+  .bss : ALIGN(4)
+  {
+    _sbss = ABSOLUTE(.);
+    *(.bss .bss.*)
+    *(.gnu.linkonce.b.*)
+    *(COMMON)
+    . = ALIGN(4);
+    _ebss = ABSOLUTE(.);
+  } > sram
+
+  .noinit (NOLOAD) : ALIGN(4)
+  {
+    *(.noinit .noinit.*)
+  } > sram
+
+  ASSERT((ORIGIN(flash) & 0x1ff) == 0,
+         "BK7258 AP vector base must be 512-byte aligned")
+  ASSERT(_vectors == ORIGIN(flash),
+         "BK7258 AP vector table must begin at the image base")
+  ASSERT(ORIGIN(sram) == 0x2802b000 && LENGTH(sram) == 0x00043c00,
+         "BK7258 AP must use the locked 271 KiB RAM window")
+  ASSERT(_ebss + BK7258_IDLE_STACK_RESERVATION <= ORIGIN(sram) + LENGTH(sram),
+         "BK7258 AP SRAM exhausted by static sections and idle stack")
+
+  .stab 0 : { *(.stab) }
+  .stabstr 0 : { *(.stabstr) }
+  .comment 0 : { *(.comment) }
+  .debug_abbrev 0 : { *(.debug_abbrev) }
+  .debug_info 0 : { *(.debug_info) }
+  .debug_line 0 : { *(.debug_line) }
+}
