+  uint32_t last_heartbeat = 0;
+  uint32_t last_report = 0;
+  uint32_t last_stage = UINT32_MAX;
+  unsigned int invalid_samples = 0;
+  unsigned int stagnant_samples = 0;
+  bool invalid_reported = false;
