+            {
+              stagnant_samples = 0;
+              stalled_reported = false;
+              last_heartbeat = record.heartbeat;
+
+              if (record.heartbeat == 1 ||
+                  record.heartbeat - last_report >=
+                    BK7258_AP_HEARTBEAT_LOG_INTERVAL)
+                {
+                  syslog(LOG_INFO, "[AP] alive seq=%u heartbeat=%u\n",
