+                         (unsigned int)record.boot_sequence,
+                         (unsigned int)record.heartbeat,
+                         stagnant_samples);
+                  stalled_reported = true;
+                }
+            }
+        }
+
+      nxsig_usleep(1000 * 1000);
+    }
+
+  return 0;
+}
