+ * board/bk7258-devkit/include/bk7258_rptun.h
+ ****************************************************************************/
+
+#ifndef __VENDOR_BEKEN_BOARD_BK7258_DEVKIT_INCLUDE_BK7258_RPTUN_H
+#define __VENDOR_BEKEN_BOARD_BK7258_DEVKIT_INCLUDE_BK7258_RPTUN_H
+
