 #define BK7258_RPTUN_BUFFER_SIZE   512
 #define BK7258_RPTUN_POLL_USEC     (10 * 1000)
+#define BK7258_RPTUN_DIAG_USEC     (5 * 1000 * 1000)
+#define BK7258_RPTUN_DIAG_MAGIC    UINT32_C(0x414d5044) /* "AMPD" */
+
+enum bk7258_rptun_stage_e
+{
+  BK7258_RPTUN_STAGE_EMPTY = 0,
+  BK7258_RPTUN_STAGE_INIT_ENTERED,
+  BK7258_RPTUN_STAGE_SHARED_SRAM_READY,
+  BK7258_RPTUN_STAGE_RPMSG_WATCH_REGISTERED,
+  BK7258_RPTUN_STAGE_RPTUN_REGISTERED,
+  BK7258_RPTUN_STAGE_RESOURCE_ENTERED,
+  BK7258_RPTUN_STAGE_RESOURCE_READY,
+  BK7258_RPTUN_STAGE_CALLBACK_REGISTERED,
+  BK7258_RPTUN_STAGE_POLL_THREAD_CREATED,
+  BK7258_RPTUN_STAGE_RPMSG_DEVICE_CREATED,
+};
+
+struct bk7258_rptun_diag_side_s
+{
+  volatile uint32_t stage;
+  volatile uint32_t polls;
+  volatile uint32_t callbacks;
+  volatile uint32_t notifies;
+  volatile int32_t last_callback_ret;
+  volatile uint32_t last_notify_vqid;
+  volatile uint32_t rpmsg_devices;
+  volatile uint32_t ping_dest;
+  volatile uint32_t ping_rt_dest;
+};
+
+struct bk7258_rptun_diag_s
+{
+  volatile uint32_t magic;
+  volatile uint32_t version;
+  struct bk7258_rptun_diag_side_s cp;
+  struct bk7258_rptun_diag_side_s ap;
+};

 struct bk7258_rptun_shmem_s
 {
   volatile uintptr_t base;
+  struct bk7258_rptun_diag_s diag;
   struct rptun_rsc_s rsc;
 };
@@
   void *callback_arg;
   struct bk7258_rptun_shmem_s *shmem;
+  struct bk7258_rptun_diag_side_s *diag;
+  struct rpmsg_device *rdev;
   bool master;
 };
@@
 static inline void bk7258_rptun_barrier(void)
@@
 }
+
+static void bk7258_rptun_set_stage(struct bk7258_rptun_dev_s *priv,
+                                   uint32_t stage)
+{
+  priv->diag->stage = stage;
+  bk7258_rptun_barrier();
+}
+
+static void bk7258_rptun_update_endpoints(struct bk7258_rptun_dev_s *priv)
+{
+  struct rpmsg_endpoint *ept;
+  struct metal_list *node;
+
+  if (priv->rdev == NULL)
+    {
+      return;
+    }
+
+  priv->diag->ping_dest = RPMSG_ADDR_ANY;
+  priv->diag->ping_rt_dest = RPMSG_ADDR_ANY;
+
+  metal_mutex_acquire(&priv->rdev->lock);
+  metal_list_for_each(&priv->rdev->endpoints, node)
+    {
+      ept = metal_container_of(node, struct rpmsg_endpoint, node);
+      if (strcmp(ept->name, "rpmsg-ping") == 0)
+        {
+          priv->diag->ping_dest = ept->dest_addr;
+        }
+      else if (strcmp(ept->name, "rpmsg-ping-rt") == 0)
+        {
+          priv->diag->ping_rt_dest = ept->dest_addr;
+        }
+    }
+
+  metal_mutex_release(&priv->rdev->lock);
+  bk7258_rptun_barrier();
+}
+
+static void bk7258_rptun_rpmsg_created(struct rpmsg_device *rdev, void *arg)
+{
+  struct bk7258_rptun_dev_s *priv = arg;
+
+  priv->rdev = rdev;
+  priv->diag->rpmsg_devices++;
+  bk7258_rptun_set_stage(priv, BK7258_RPTUN_STAGE_RPMSG_DEVICE_CREATED);
+  bk7258_rptun_update_endpoints(priv);
+}
+
+static void bk7258_rptun_rpmsg_destroyed(struct rpmsg_device *rdev, void *arg)
+{
+  struct bk7258_rptun_dev_s *priv = arg;
+
+  if (priv->rdev == rdev)
+    {
+      priv->rdev = NULL;
+      priv->diag->ping_dest = RPMSG_ADDR_ANY;
+      priv->diag->ping_rt_dest = RPMSG_ADDR_ANY;
+      bk7258_rptun_barrier();
+    }
+}
@@
   size_t carveout_size;
+
+  bk7258_rptun_set_stage(priv, BK7258_RPTUN_STAGE_RESOURCE_ENTERED);
@@
       bk7258_rptun_barrier();
     }

+  bk7258_rptun_set_stage(priv, BK7258_RPTUN_STAGE_RESOURCE_READY);
   return &rsc->rsc_tbl_hdr;
 }
@@
   (void)dev;
-  (void)vqid;
+  g_bk7258_rptun.diag->notifies++;
+  g_bk7258_rptun.diag->last_notify_vqid = vqid;
   bk7258_rptun_barrier();
@@
   priv->callback = callback;
   priv->callback_arg = arg;
+  bk7258_rptun_set_stage(priv, BK7258_RPTUN_STAGE_CALLBACK_REGISTERED);
   return 0;
 }
@@
       if (priv->callback != NULL)
         {
+          int ret;
+
           bk7258_rptun_barrier();
-          priv->callback(priv->callback_arg, RPTUN_NOTIFY_ALL);
+          priv->diag->polls++;
+          ret = priv->callback(priv->callback_arg, RPTUN_NOTIFY_ALL);
+          priv->diag->callbacks++;
+          priv->diag->last_callback_ret = ret;
+          bk7258_rptun_update_endpoints(priv);
+          bk7258_rptun_barrier();
         }
@@
   return 0;
 }
+
+#ifdef CONFIG_BK7258_COMPONENT_CP
+static void bk7258_rptun_read_vring(struct fw_rsc_vdev_vring *rsc_vring,
+                                    uint16_t *avail, uint16_t *used)
+{
+  struct vring vring;
+
+  *avail = 0;
+  *used = 0;
+  if (rsc_vring->da == 0 || rsc_vring->da == FW_RSC_U32_ADDR_ANY)
+    {
+      return;
+    }
+
+  vring_init(&vring, rsc_vring->num, (uint8_t *)(uintptr_t)rsc_vring->da,
+             rsc_vring->align);
+  bk7258_rptun_barrier();
+  *avail = vring.avail->idx;
+  *used = vring.used->idx;
+}
+
+static int bk7258_rptun_diag_thread(int argc, char *argv[])
+{
+  struct bk7258_rptun_shmem_s *shmem = g_bk7258_rptun.shmem;
+  uint16_t r0_avail;
+  uint16_t r0_used;
+  uint16_t r1_avail;
+  uint16_t r1_used;
+
+  (void)argc;
+  (void)argv;
+
+  for (; ; )
+    {
+      bk7258_rptun_barrier();
+      bk7258_rptun_read_vring(&shmem->rsc.rpmsg_vring0,
+                              &r0_avail, &r0_used);
+      bk7258_rptun_read_vring(&shmem->rsc.rpmsg_vring1,
+                              &r1_avail, &r1_used);
+      syslog(LOG_INFO,
+             "[AMP] cp{s=%u p=%u cb=%u n=%u ret=%d d=%08x/%08x} "
+             "ap{s=%u p=%u cb=%u n=%u ret=%d d=%08x/%08x} "
+             "r0=%u/%u r1=%u/%u v=%02x\n",
+             shmem->diag.cp.stage, shmem->diag.cp.polls,
+             shmem->diag.cp.callbacks, shmem->diag.cp.notifies,
+             shmem->diag.cp.last_callback_ret, shmem->diag.cp.ping_dest,
+             shmem->diag.cp.ping_rt_dest, shmem->diag.ap.stage,
+             shmem->diag.ap.polls, shmem->diag.ap.callbacks,
+             shmem->diag.ap.notifies, shmem->diag.ap.last_callback_ret,
+             shmem->diag.ap.ping_dest, shmem->diag.ap.ping_rt_dest,
+             r0_avail, r0_used, r1_avail, r1_used,
+             shmem->rsc.rpmsg_vdev.status);
+      nxsig_usleep(BK7258_RPTUN_DIAG_USEC);
+    }
+
+  return 0;
+}
+#endif

 int bk7258_rptun_initialize(void)
 {
   int ret;
@@
   if (g_bk7258_rptun.master)
     {
       memset(g_bk7258_rptun.shmem, 0, CONFIG_BK7258_RPMSG_SHM_SIZE);
+      g_bk7258_rptun.shmem->diag.magic = BK7258_RPTUN_DIAG_MAGIC;
+      g_bk7258_rptun.shmem->diag.version = 1;
+      g_bk7258_rptun.shmem->diag.cp.ping_dest = RPMSG_ADDR_ANY;
+      g_bk7258_rptun.shmem->diag.cp.ping_rt_dest = RPMSG_ADDR_ANY;
+      g_bk7258_rptun.shmem->diag.ap.ping_dest = RPMSG_ADDR_ANY;
+      g_bk7258_rptun.shmem->diag.ap.ping_rt_dest = RPMSG_ADDR_ANY;
       bk7258_rptun_barrier();
     }
+
+#ifdef CONFIG_BK7258_COMPONENT_CP
+  g_bk7258_rptun.diag = &g_bk7258_rptun.shmem->diag.cp;
+#else
+  g_bk7258_rptun.diag = &g_bk7258_rptun.shmem->diag.ap;
+#endif
+  bk7258_rptun_set_stage(&g_bk7258_rptun,
+                         BK7258_RPTUN_STAGE_INIT_ENTERED);

   ret = rptun_initialize(&g_bk7258_rptun.rptun);
@@
       return ret;
     }
+
+  bk7258_rptun_set_stage(&g_bk7258_rptun,
+                         BK7258_RPTUN_STAGE_RPTUN_REGISTERED);
+
+  ret = rpmsg_register_callback(&g_bk7258_rptun,
