+
+static void bk7258_rptun_update_shared_state(
+  struct bk7258_rptun_dev_s *priv)
+{
+  struct fw_rsc_vdev_vring *rsc_vring;
+  struct vring vring;
+  uint32_t *avail;
+  uint32_t *used;
+  unsigned int index;
+
+  priv->diag->vdev_status = priv->shmem->rsc.rpmsg_vdev.status;
+  for (index = 0; index < BK7258_RPTUN_VRINGS; index++)
+    {
+      if (index == 0)
+        {
+          rsc_vring = &priv->shmem->rsc.rpmsg_vring0;
+          avail = (uint32_t *)&priv->diag->vring0_avail;
+          used = (uint32_t *)&priv->diag->vring0_used;
+        }
+      else
+        {
+          rsc_vring = &priv->shmem->rsc.rpmsg_vring1;
+          avail = (uint32_t *)&priv->diag->vring1_avail;
+          used = (uint32_t *)&priv->diag->vring1_used;
+        }
+
+      *avail = 0;
+      *used = 0;
+      if (rsc_vring->da == 0 || rsc_vring->da == FW_RSC_U32_ADDR_ANY)
+        {
+          continue;
+        }
+
+      vring_init(&vring, rsc_vring->num,
+                 (uint8_t *)(uintptr_t)rsc_vring->da,
+                 rsc_vring->align);
+      bk7258_rptun_barrier();
+      *avail = vring.avail->idx;
+      *used = vring.used->idx;
+    }
+
+  bk7258_rptun_barrier();
+}
