*** Begin Patch
*** Update File: board/bk7258-devkit/src/bk7258_rptun.c
@@
 #include <stdint.h>
 #include <string.h>
-#include <syslog.h>
 #include <sys/param.h>
+#include <sys/stat.h>
+#include <syslog.h>
@@
   volatile uint32_t vring0_used;
   volatile uint32_t vring1_avail;
   volatile uint32_t vring1_used;
+  volatile uint32_t rpmsg_node;
 };
@@
 static int bk7258_rptun_poll_thread(int argc, char *argv[])
 {
   struct bk7258_rptun_dev_s *priv = &g_bk7258_rptun;
+#ifdef CONFIG_BK7258_COMPONENT_AP
+  struct stat statbuf;
+#endif
@@
       if (priv->callback != NULL)
         {
@@
           bk7258_rptun_barrier();
         }
+
+#ifdef CONFIG_BK7258_COMPONENT_AP
+      priv->diag->rpmsg_node = stat("/dev/rpmsg/cp", &statbuf) == 0;
+      bk7258_rptun_barrier();
+#endif

       nxsig_usleep(BK7258_RPTUN_POLL_USEC);
@@
-      syslog(LOG_INFO, "[AMP-A] s=%u p=%u cb=%u n=%u ret=%d v=%02x\n",
+      syslog(LOG_INFO,
+             "[AMP-A] s=%u p=%u cb=%u n=%u ret=%d v=%02x dev=%u\n",
              shmem->diag.ap.stage,
              shmem->diag.ap.polls, shmem->diag.ap.callbacks,
              shmem->diag.ap.notifies, shmem->diag.ap.last_callback_ret,
-             shmem->diag.ap.vdev_status);
+             shmem->diag.ap.vdev_status, shmem->diag.ap.rpmsg_node);
*** End Patch

