+/****************************************************************************
+ * board/bk7258-devkit/src/bk7258_rpmsg_diag_wrap.c
+ *
+ * Temporary AP-only link wrappers used to isolate RPMsg startup failures
+ * without modifying the upstream NuttX/OpenAMP sources.
+ ****************************************************************************/
+
+#include <nuttx/config.h>
+
+#if defined(CONFIG_RPTUN) && defined(CONFIG_BK7258_COMPONENT_AP)
+
+#include <limits.h>
+#include <stdint.h>
+
+#include <nuttx/wqueue.h>
+
+#include <openamp/rpmsg_virtio.h>
+
+#include "bk7258_rptun.h"
+
+struct rpmsg_s;
+struct rpmsg_ops_s;
+
+int __real_rpmsg_queue_work(struct rpmsg_s *rpmsg, uint8_t priority,
+                            struct work_s *work, worker_t worker, void *arg);
+int __real_rpmsg_register(const char *path, struct rpmsg_s *rpmsg,
+                          const struct rpmsg_ops_s *ops, uint16_t nrx);
+int __real_rpmsg_init_vdev_with_config(
+  struct rpmsg_virtio_device *rvdev, struct virtio_device *vdev,
+  rpmsg_ns_bind_cb ns_bind_cb, struct metal_io_region *shm_io,
+  struct rpmsg_virtio_shm_pool *shpool,
+  const struct rpmsg_virtio_config *config);
+
+int __wrap_rpmsg_queue_work(struct rpmsg_s *rpmsg, uint8_t priority,
+                            struct work_s *work, worker_t worker, void *arg)
+{
+  int ret;
+
+  bk7258_rptun_diag_call(BK7258_RPTUN_DIAG_QUEUE_WORK, INT_MIN, false);
+  ret = __real_rpmsg_queue_work(rpmsg, priority, work, worker, arg);
+  bk7258_rptun_diag_call(BK7258_RPTUN_DIAG_QUEUE_WORK, ret, true);
+  return ret;
+}
+
+int __wrap_rpmsg_register(const char *path, struct rpmsg_s *rpmsg,
+                          const struct rpmsg_ops_s *ops, uint16_t nrx)
+{
+  int ret;
+
+  bk7258_rptun_diag_call(BK7258_RPTUN_DIAG_REGISTER, INT_MIN, false);
+  ret = __real_rpmsg_register(path, rpmsg, ops, nrx);
+  bk7258_rptun_diag_call(BK7258_RPTUN_DIAG_REGISTER, ret, true);
+  return ret;
+}
+
+int __wrap_rpmsg_init_vdev_with_config(
+  struct rpmsg_virtio_device *rvdev, struct virtio_device *vdev,
+  rpmsg_ns_bind_cb ns_bind_cb, struct metal_io_region *shm_io,
+  struct rpmsg_virtio_shm_pool *shpool,
+  const struct rpmsg_virtio_config *config)
+{
+  int ret;
+
+  bk7258_rptun_diag_call(BK7258_RPTUN_DIAG_INIT_VDEV, INT_MIN, false);
+  ret = __real_rpmsg_init_vdev_with_config(rvdev, vdev, ns_bind_cb, shm_io,
+                                           shpool, config);
+  bk7258_rptun_diag_call(BK7258_RPTUN_DIAG_INIT_VDEV, ret, true);
+  return ret;
+}
+
+#endif
