@@
 int __wrap_rpmsg_queue_work(struct rpmsg_s *rpmsg, uint8_t priority,
                             struct work_s *work, worker_t worker, void *arg)
 {
   int ret;

   bk7258_rptun_diag_call(BK7258_RPTUN_DIAG_QUEUE_WORK, INT_MIN, false);
-  ret = __real_rpmsg_queue_work(rpmsg, priority, work, worker, arg);
+
+  /* A2-1 receives all notifications from the board polling kthread. The AP
+   * dynamic RPMsg work queue creates its worker successfully, but its first
+   * zero-delay work submission never returns and the worker remains blocked
+   * on its semaphore. Execute work synchronously while we are in thread
+   * context so the remaining VirtIO/RPMsg/NS path can be validated. Keep the
+   * upstream asynchronous path for a future Mailbox ISR context. */
+
+  if (!up_interrupt_context())
+    {
+      worker(arg);
+      ret = 0;
+    }
+  else
+    {
+      ret = __real_rpmsg_queue_work(rpmsg, priority, work, worker, arg);
+    }
+
   bk7258_rptun_diag_call(BK7258_RPTUN_DIAG_QUEUE_WORK, ret, true);
   return ret;
 }
